#include <bits/stdc++.h>
using namespace std;

struct TwoSAT {
    int n;
    vector<vector<int>> adj, radj;
    vector<int> order, comp;
    vector<bool> vis, assignment;

    TwoSAT(int n) : n(n) {
        adj.resize(2 * n);
        radj.resize(2 * n);
    }

    void add_impl(int u, int v) {
        adj[u].push_back(v);
        radj[v].push_back(u);
    }

    void add_or(int u, int v) {
        add_impl(u ^ 1, v);
        add_impl(v ^ 1, u);
    }

    void dfs1(int u) {
        vis[u] = true;
        for (int v : adj[u])
            if (!vis[v]) dfs1(v);
        order.push_back(u);
    }

    void dfs2(int u, int cl) {
        comp[u] = cl;
        for (int v : radj[u])
            if (comp[v] == -1) dfs2(v, cl);
    }

    bool solve() {
        vis.assign(2 * n, false);
        for (int i = 0; i < 2 * n; i++)
            if (!vis[i]) dfs1(i);
        comp.assign(2 * n, -1);
        int cur = 0;
        for (int i = 2 * n - 1; i >= 0; i--) {
            int u = order[i];
            if (comp[u] == -1) dfs2(u, cur++);
        }
        assignment.assign(n, false);
        for (int i = 0; i < n; i++) {
            if (comp[2 * i] == comp[2 * i + 1]) return false;
            assignment[i] = (comp[2 * i] > comp[2 * i + 1]);
        }
        return true;
    }
};

