#include <bits/stdc++.h>
using namespace std;

/*
We model each possible placement as a boolean variable:
for flag i:
  false -> choose X[i]
  true  -> choose Y[i]

If two choices are too close (< D), they cannot both be selected.
This gives a 2-SAT instance.

Literal encoding:
  node 2*i     = choose X[i]   (false)
  node 2*i + 1 = choose Y[i]   (true)

If choice a and choice b conflict, add:
  a -> not b
  b -> not a

Also, for each flag, exactly one of X[i], Y[i] must be chosen.
In 2-SAT with one variable, this is already ensured by using the variable itself:
choosing X means false, choosing Y means true.
The only extra impossible case for the same flag is if |X[i]-Y[i]| < D, but that does NOT matter,
because we choose only one of them, never both.

After building implications, run SCC (Kosaraju).
If a variable and its negation are in the same SCC, impossible.
Otherwise assign by SCC topological order.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long D;
    cin >> N >> D;

    vector<long long> X(N), Y(N);
    for (int i = 0; i < N; ++i) cin >> X[i] >> Y[i];

    int M = 2 * N;
    vector<vector<int>> g(M), rg(M);

    auto neg = [&](int v) {
        return v ^ 1;
    };

    auto add_imp = [&](int a, int b) {
        g[a].push_back(b);
        rg[b].push_back(a);
    };

    auto add_or = [&](int a, int b) {
        // (a OR b) == (!a -> b) and (!b -> a)
        add_imp(neg(a), b);
        add_imp(neg(b), a);
    };

    // node( i, 0 ) = choose X[i]
    // node( i, 1 ) = choose Y[i]
    auto node = [&](int i, int t) {
        return 2 * i + t;
    };

    // Conflict checking between every pair of flags
    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            // X[i] with X[j]
            if (llabs(X[i] - X[j]) < D) {
                int a = node(i, 0), b = node(j, 0);
                // not (a and b) => (!a or !b)
                add_or(neg(a), neg(b));
            }
            // X[i] with Y[j]
            if (llabs(X[i] - Y[j]) < D) {
                int a = node(i, 0), b = node(j, 1);
                add_or(neg(a), neg(b));
            }
            // Y[i] with X[j]
            if (llabs(Y[i] - X[j]) < D) {
                int a = node(i, 1), b = node(j, 0);
                add_or(neg(a), neg(b));
            }
            // Y[i] with Y[j]
            if (llabs(Y[i] - Y[j]) < D) {
                int a = node(i, 1), b = node(j, 1);
                add_or(neg(a), neg(b));
            }
        }
    }

    // Kosaraju
    vector<int> order, vis(M, 0);
    function<void(int)> dfs1 = [&](int v) {
        vis[v] = 1;
        for (int to : g[v]) if (!vis[to]) dfs1(to);
        order.push_back(v);
    };

    for (int i = 0; i < M; ++i) {
        if (!vis[i]) dfs1(i);
    }

    vector<int> comp(M, -1);
    function<void(int,int)> dfs2 = [&](int v, int c) {
        comp[v] = c;
        for (int to : rg[v]) if (comp[to] == -1) dfs2(to, c);
    };

    int cid = 0;
    for (int i = M - 1; i >= 0; --i) {
        int v = order[i];
        if (comp[v] == -1) dfs2(v, cid++);
    }

    for (int i = 0; i < N; ++i) {
        if (comp[node(i, 0)] == comp[node(i, 1)]) {
            cout << "No\n";
            return 0;
        }
    }

    cout << "Yes\n";
    vector<long long> ans(N);
    for (int i = 0; i < N; ++i) {
        // Larger component number comes earlier in topological assignment
        // If comp[X] > comp[Y], choose X; else choose Y
        if (comp[node(i, 0)] > comp[node(i, 1)]) ans[i] = X[i];
        else ans[i] = Y[i];
    }

    for (int i = 0; i < N; ++i) {
        cout << ans[i] << '\n';
    }

    return 0;
}

