                add_edge(2*i+1, 2*j);
                add_edge(2*j+1, 2*i);
            }
        }
    }

    // Kosaraju's algorithm
    memset(visited, 0, sizeof(visited));
    order_cnt = 0;
    for (int i = 0; i < 2*n; i++)
