#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int to, next;
} Edge;

static void add_edge(Edge *edges, int *head, int *ecnt, int u, int v) {
    edges[*ecnt].to = v;
    edges[*ecnt].next = head[u];
    head[u] = (*ecnt)++;
}

int main(void) {
    int N;
    ll D;
    if (scanf("%d %lld", &N, &D) != 2) return 0;

    ll *X = (ll *)malloc(sizeof(ll) * N);
    ll *Y = (ll *)malloc(sizeof(ll) * N);

    for (int i = 0; i < N; i++) {
        scanf("%lld %lld", &X[i], &Y[i]);
    }

    /*
      2-SAT:
      variable i:
        false -> choose X[i]
        true  -> choose Y[i]

      node 2*i     = false
      node 2*i + 1 = true

      If two choices conflict, they cannot both be chosen.
      For literals a and b with constraint !(a && b):
        a -> !b
        b -> !a
    */

    int vars = N;
    int V = 2 * vars;

    /* Worst-case edges: for each pair (i,j), 4 possible conflicts, each adds 2 implications */
    long long maxPairs = (long long)N * (N - 1) / 2;
    long long maxEdgesLL = maxPairs * 8 + 5;
    Edge *g = (Edge *)malloc(sizeof(Edge) * maxEdgesLL);
    Edge *rg = (Edge *)malloc(sizeof(Edge) * maxEdgesLL);
    int *head = (int *)malloc(sizeof(int) * V);
    int *rhead = (int *)malloc(sizeof(int) * V);

    for (int i = 0; i < V; i++) head[i] = rhead[i] = -1;
    int ecnt = 0, recnt = 0;

    #define NODE(i, val) (2*(i) + ((val) ? 1 : 0))
    #define NEG(x) ((x) ^ 1)

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            if (llabs(X[i] - X[j]) < D) {
                int a = NODE(i, 0), b = NODE(j, 0);
                add_edge(g, head, &ecnt, a, NEG(b));
                add_edge(g, head, &ecnt, b, NEG(a));
                add_edge(rg, rhead, &recnt, NEG(b), a);
                add_edge(rg, rhead, &recnt, NEG(a), b);
            }
            if (llabs(X[i] - Y[j]) < D) {
                int a = NODE(i, 0), b = NODE(j, 1);
                add_edge(g, head, &ecnt, a, NEG(b));
                add_edge(g, head, &ecnt, b, NEG(a));
                add_edge(rg, rhead, &recnt, NEG(b), a);
                add_edge(rg, rhead, &recnt, NEG(a), b);
            }
            if (llabs(Y[i] - X[j]) < D) {
                int a = NODE(i, 1), b = NODE(j, 0);
                add_edge(g, head, &ecnt, a, NEG(b));
                add_edge(g, head, &ecnt, b, NEG(a));
                add_edge(rg, rhead, &recnt, NEG(b), a);
                add_edge(rg, rhead, &recnt, NEG(a), b);
            }
            if (llabs(Y[i] - Y[j]) < D) {
                int a = NODE(i, 1), b = NODE(j, 1);
                add_edge(g, head, &ecnt, a, NEG(b));
                add_edge(g, head, &ecnt, b, NEG(a));
                add_edge(rg, rhead, &recnt, NEG(b), a);
                add_edge(rg, rhead, &recnt, NEG(a), b);
            }
        }
    }

    /* Kosaraju */
    int *used = (int *)calloc(V, sizeof(int));
    int *order = (int *)malloc(sizeof(int) * V);
    int ordsz = 0;

    /* iterative DFS for first pass */
    int *stack_v = (int *)malloc(sizeof(int) * V);
    int *stack_e = (int *)malloc(sizeof(int) * V);

    for (int s = 0; s < V; s++) {
        if (used[s]) continue;

        int top = 0;
        stack_v[top] = s;
        stack_e[top] = head[s];
        used[s] = 1;
        top++;

        while (top > 0) {
            int v = stack_v[top - 1];
            int *pe = &stack_e[top - 1];
            int e = *pe;

            while (e != -1 && used[g[e].to]) e = g[e].next;
            *pe = e;

            if (e == -1) {
                order[ordsz++] = v;
                top--;
            } else {
                int to = g[e].to;
                *pe = g[e].next;
                used[to] = 1;
                stack_v[top] = to;
                stack_e[top] = head[to];
                top++;
            }
        }
    }

    int *comp = (int *)malloc(sizeof(int) * V);
    for (int i = 0; i < V; i++) comp[i] = -1;

    int cid = 0;
    for (int idx = V - 1; idx >= 0; idx--) {
        int s = order[idx];
        if (comp[s] != -1) continue;

        int top = 0;
        stack_v[top++] = s;
        comp[s] = cid;

        while (top > 0) {
            int v = stack_v[--top];
            for (int e = rhead[v]; e != -1; e = rg[e].next) {
                int to = rg[e].to;
                if (comp[to] == -1) {
                    comp[to] = cid;
                    stack_v[top++] = to;
                }
            }
        }
        cid++;
    }

    ll *ans = (ll *)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) {
        if (comp[NODE(i, 0)] == comp[NODE(i, 1)]) {
            printf("No\n");
            free(X); free(Y); free(g); free(rg); free(head); free(rhead);
            free(used); free(order); free(stack_v); free(stack_e); free(comp); free(ans);
            return 0;
        }
        /* Larger topological order comes earlier in assignment rule */
        if (comp[NODE(i, 1)] > comp[NODE(i, 0)]) ans[i] = Y[i];
        else ans[i] = X[i];
    }

    printf("Yes\n");
    for (int i = 0; i < N; i++) {
        printf("%lld\n", ans[i]);
    }

    free(X); free(Y); free(g); free(rg); free(head); free(rhead);
    free(used); free(order); free(stack_v); free(stack_e); free(comp); free(ans);
    return 0;
}

