public class FlagsPlacement {

    static class TwoSAT {
        int n;
        List<Integer>[] graph, revGraph;
        boolean[] visited;
        int[] comp;
        List<Integer> order;

        TwoSAT(int variables) {
            n = variables * 2;
            graph = new ArrayList[n];
            revGraph = new ArrayList[n];
            for (int i = 0; i < n; i++) {
                graph[i] = new ArrayList<>();
                revGraph[i] = new ArrayList<>();
            }
            visited = new boolean[n];
            comp = new int[n];
            order = new ArrayList<>();
        }

        void addImplication(int u, int v) {
            graph[u].add(v);
            revGraph[v].add(u);
        }

        void addOr(int u, int v) {
            addImplication(u ^ 1, v);
            addImplication(v ^ 1, u);
        }

        void dfs1(int u) {
            visited[u] = true;
            for (int v : graph[u]) {
                if (!visited[v]) dfs1(v);
            }
            order.add(u);
        }

        void dfs2(int u, int id) {
            comp[u] = id;
            for (int v : revGraph[u]) {
                if (comp[v] == -1) dfs2(v, id);
            }
        }

        boolean solve() {
            Arrays.fill(visited, false);
            for (int i = 0; i < n; i++) if (!visited[i]) dfs1(i);
            Arrays.fill(comp, -1);
            int id = 0;
            for (int i = n - 1; i >= 0; i--) {
                int u = order.get(i);
                if (comp[u] == -1) dfs2(u, id++);
            }
            for (int i = 0; i < n; i += 2) {
                if (comp[i] == comp[i + 1]) return false;
            }
            return true;
        }

        boolean[] assignment() {
            boolean[] res = new boolean[n / 2];
            for (int i = 0; i < n / 2; i++) {
                res[i] = comp[2 * i] > comp[2 * i + 1];
            }
            return res;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        long D = Long.parseLong(st.nextToken());

        long[] X = new long[N];
        long[] Y = new long[N];
        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            X[i] = Long.parseLong(st.nextToken());
            Y[i] = Long.parseLong(st.nextToken());
        }

        TwoSAT sat = new TwoSAT(N);

        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                // If distance between X_i and X_j < D, they can't both be chosen
                if (Math.abs(X[i] - X[j]) < D) {
                    sat.addOr(2 * i, 2 * j); // not (i0 and j0) => (i1 or j1) in variable form
                    // Actually: clause: (¬i0 ∨ ¬j0)
                    sat.addImplication(2 * i, 2 * j + 1);
                    sat.addImplication(2 * j, 2 * i + 1);
                }
                if (Math.abs(X[i] - Y[j]) < D) {
                    sat.addImplication(2 * i, 2 * j);
                    sat.addImplication(2 * j + 1, 2 * i + 1);
                }
                if (Math.abs(Y[i] - X[j]) < D) {
                    sat.addImplication(2 * i + 1, 2 * j + 1);
                    sat.addImplication(2 * j, 2 * i);
                }
                if (Math.abs(Y[i] - Y[j]) < D) {
                    sat.addImplication(2 * i + 1, 2 * j);
                    sat.addImplication(2 * j + 1, 2 * i);
                }
            }
        }

        if (!sat.solve()) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            boolean[] assign = sat.assignment();
            for (int i = 0; i < N; i++) {
                System.out.println(assign[i] ? X[i] : Y[i]);
            }
        }
    }
}

