            Y[i] = sc.nextLong();
        }

        int vars = 2 * n;
        adj = new List[vars];
        radj = new List[vars];
        for (int i = 0; i < vars; i++) {
            adj[i] = new ArrayList<>();
            radj[i] = new ArrayList<>();
        }

        // literal: 2*i = X_i chosen, 2*i+1 = Y_i chosen
        // neg(2*i) = 2*i+1, neg(2*i+1) = 2*i

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                // Check all 4 combinations
                long[][] pos = {{X[i], X[j]}, {X[i], Y[j]}, {Y[i], X[j]}, {Y[i], Y[j]}};
                int[] litI = {2*i, 2*i, 2*i+1, 2*i+1};
                int[] litJ = {2*j, 2*j+1, 2*j, 2*j+1};

                for (int k = 0; k < 4; k++) {
                    if (Math.abs(pos[k][0] - pos[k][1]) < D) {
                        // litI[k] AND litJ[k] is forbidden
                        // Add: litI[k] -> neg(litJ[k]) and litJ[k] -> neg(litI[k])
                        int a = litI[k], b = litJ[k];
                        int na = a ^ 1, nb = b ^ 1;
                        addImpl(a, nb);
                        addImpl(b, na);
                    }
                }
            }
        }

        // Kosaraju's SCC
        order = new int[vars];
        comp = new int[vars];
        visited = new boolean[vars];
        idx = 0;
        Arrays.fill(comp, -1);

        for (int i = 0; i < vars; i++)
            if (!visited[i]) dfs1(i);

        int c = 0;
        for (int i = vars - 1; i >= 0; i--) {
            if (comp[order[i]] == -1) dfs2(order[i], c++);
        }

        // Check satisfiability
        for (int i = 0; i < n; i++) {
            if (comp[2*i] == comp[2*i+1]) {
                System.out.println("No");
                return;
            }
        }

        System.out.println("Yes");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            // Choose the literal with higher comp number (in Kosaraju, higher comp = earlier in reverse order = true in assignment)
            if (comp[2*i] > comp[2*i+1]) {
                sb.append(X[i]);
            } else {
                sb.append(Y[i]);
            }
            if (i < n-1) sb.append('\n');
        }
        System.out.println(sb);
    }

    static void addImpl(int u, int v) {
        adj[u].add(v);
        radj[v].add(u);
    }

    static void dfs1(int v) {
        visited[v] = true;
        for (int u : adj[v]) if (!visited[u]) dfs1(u);
        order[idx++] = v;
    }

    static void dfs2(int v, int c) {
        comp[v] = c;
        for (int u : radj[v]) if (comp[u] == -1) dfs2(u, c);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class TwoSAT {
        int n;
        ArrayList<Integer>[] g, rg;
        boolean[] assignment;

        @SuppressWarnings("unchecked")
        TwoSAT(int n) {
            this.n = n;
            g = new ArrayList[2 * n];
            rg = new ArrayList[2 * n];
            for (int i = 0; i < 2 * n; i++) {
                g[i] = new ArrayList<>();
                rg[i] = new ArrayList<>();
            }
        }

        int var(int i, boolean val) {
            // false -> 2*i, true -> 2*i+1
            return 2 * i + (val ? 1 : 0);
        }

        int neg(int x) {
            return x ^ 1;
        }

        void addImplication(int a, int b) {
            g[a].add(b);
            rg[b].add(a);
        }

        void addOr(int a, int b) {
            // a OR b
            addImplication(neg(a), b);
            addImplication(neg(b), a);
        }

        void addNand(int a, int b) {
            // not (a and b) == (!a or !b)
            addOr(neg(a), neg(b));
        }

        boolean satisfiable() {
            int m = 2 * n;
            boolean[] used = new boolean[m];
            int[] order = new int[m];
            int ordPtr = 0;

            for (int i = 0; i < m; i++) {
                if (!used[i]) {
                    ordPtr = dfs1Iter(i, used, order, ordPtr);
                }
            }

            int[] comp = new int[m];
            Arrays.fill(comp, -1);
            int cid = 0;
            for (int i = m - 1; i >= 0; i--) {
                int v = order[i];
                if (comp[v] == -1) {
                    dfs2Iter(v, cid++, comp);
                }
            }

            assignment = new boolean[n];
            for (int i = 0; i < n; i++) {
                if (comp[2 * i] == comp[2 * i + 1]) return false;
                assignment[i] = comp[2 * i] < comp[2 * i + 1];
            }
            return true;
        }

        int dfs1Iter(int start, boolean[] used, int[] order, int ordPtr) {
            ArrayDeque<int[]> st = new ArrayDeque<>();
            st.push(new int[]{start, 0});
            used[start] = true;

            while (!st.isEmpty()) {
                int[] cur = st.peek();
                int v = cur[0];
                int idx = cur[1];

                if (idx < g[v].size()) {
                    int to = g[v].get(idx);
                    cur[1]++;
                    if (!used[to]) {
                        used[to] = true;
                        st.push(new int[]{to, 0});
                    }
                } else {
                    st.pop();
                    order[ordPtr++] = v;
                }
            }
            return ordPtr;
        }

        void dfs2Iter(int start, int cid, int[] comp) {
            ArrayDeque<Integer> st = new ArrayDeque<>();
            st.push(start);
            comp[start] = cid;
            while (!st.isEmpty()) {
                int v = st.pop();
                for (int to : rg[v]) {
                    if (comp[to] == -1) {
                        comp[to] = cid;
                        st.push(to);
                    }
                }
            }
        }
    }

    static class Point {
        long pos;
        int flag;
        int choice; // 0 -> X, 1 -> Y

        Point(long pos, int flag, int choice) {
            this.pos = pos;
            this.flag = flag;
            this.choice = choice;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        long D = fs.nextLong();

        long[] X = new long[N];
        long[] Y = new long[N];
        Point[] pts = new Point[2 * N];

        for (int i = 0; i < N; i++) {
            X[i] = fs.nextLong();
            Y[i] = fs.nextLong();
            pts[2 * i] = new Point(X[i], i, 0);
            pts[2 * i + 1] = new Point(Y[i], i, 1);
        }

        Arrays.sort(pts, Comparator.comparingLong(a -> a.pos));

        TwoSAT sat = new TwoSAT(N);

        // Variable i:
        // true  -> choose Y_i
        // false -> choose X_i

        for (int i = 0; i < 2 * N; i++) {
            for (int j = i + 1; j < 2 * N && pts[j].pos - pts[i].pos < D; j++) {
                int fi = pts[i].flag;
                int fj = pts[j].flag;
                if (fi == fj) continue;

                boolean vali = (pts[i].choice == 1); // choosing this point means variable = choice
                boolean valj = (pts[j].choice == 1);

                int li = sat.var(fi, vali);
                int lj = sat.var(fj, valj);

                // Cannot choose both these positions simultaneously
                sat.addNand(li, lj);
            }
        }

        StringBuilder out = new StringBuilder();
        if (!sat.satisfiable()) {
            out.append("No\n");
        } else {
            out.append("Yes\n");
            for (int i = 0; i < N; i++) {
                out.append(sat.assignment[i] ? Y[i] : X[i]).append('\n');
            }
        }
        System.out.print(out.toString());
    }
}

