    # node 2*i = true literal, 2*i+1 = false literal
    n = N
    size = 2 * n
    graph = [[] for _ in range(size)]
    rgraph = [[] for _ in range(size)]

    def add_clause(u, v):
        # clause: u OR v => (NOT u -> v) AND (NOT v -> u)
        # u and v are literals (2*i for true, 2*i+1 for false)
        nu = u ^ 1
        nv = v ^ 1
        graph[nu].append(v)
        graph[nv].append(u)
        rgraph[v].append(nu)
        rgraph[u].append(nv)

    def neg(u):
        return u ^ 1

    for i in range(n):
        for j in range(i+1, n):
            # Check all 4 combinations
            positions = [(X[i], X[j], 2*i, 2*j),
                         (X[i], Y[j], 2*i, 2*j+1),
                         (Y[i], X[j], 2*i+1, 2*j),
                         (Y[i], Y[j], 2*i+1, 2*j+1)]
            for pi, pj, li, lj in positions:
                if abs(pi - pj) < D:
                    # NOT li OR NOT lj
                    add_clause(neg(li), neg(lj))

    # Kosaraju's SCC
    order = []
    visited = [False] * size

    def dfs1(v):
        stack = [(v, 0)]
        while stack:
            node, state = stack.pop()
            if state == 0:
                if visited[node]:
                    continue
                visited[node] = True
                stack.append((node, 1))
                for w in graph[node]:
                    if not visited[w]:
                        stack.append((w, 0))
            else:
                order.append(node)

    for v in range(size):
        if not visited[v]:
            dfs1(v)

    comp = [-1] * size
    c = 0

    def dfs2(v, c):
        stack = [v]
        while stack:
            node = stack.pop()
            if comp[node] != -1:
                continue
            comp[node] = c
            for w in rgraph[node]:
                if comp[w] == -1:
                    stack.append(w)

    for v in reversed(order):
        if comp[v] == -1:
            dfs2(v, c)
            c += 1

    result = []
    possible = True
    for i in range(n):
