            possible = False
            break
        # In Kosaraju's, lower comp number = later in topological order
        # Variable is true if comp[true] > comp[false]... 
        # Actually: variable is true if comp[2*i] > comp[2*i+1]
        if comp[2*i] > comp[2*i+1]:
